import app from 'flarum/forum/app';
import Avatar from 'flarum/common/components/Avatar';
import Link from 'flarum/common/components/Link';
import classList from 'flarum/common/utils/classList';
import { t } from '../api';

/** People arrive as one compact list; the forum's store lets Avatar and names draw them the usual way. */
export function pushUsers(users) {
  for (const user of users) {
    app.store.pushObject({
      type: 'users',
      id: String(user.id),
      attributes: {
        username: user.username,
        displayName: user.displayName,
        slug: user.slug,
        avatarUrl: user.avatarUrl
      }
    });
  }
}
export function user(id) {
  return id ? app.store.getById('users', String(id)) : null;
}
export function Person({
  id,
  avatar = true
}) {
  const person = user(id);
  if (!person) return m("span", {
    className: "StoryChainPerson StoryChainPerson--gone"
  }, t('story.deleted_user'));
  return m(Link, {
    className: "StoryChainPerson",
    href: app.route.user(person)
  }, avatar && m(Avatar, {
    user: person
  }), m("span", {
    className: "StoryChainPerson-name"
  }, person.displayName()));
}

/** A book from the library: cover colour, title, ornament and its size. */
export function Book({
  story,
  size = 'normal'
}) {
  return m("div", {
    className: classList('StoryChainBook', `StoryChain-cover--${story.cover}`, size === 'small' && 'StoryChainBook--small'),
    "aria-hidden": "true"
  }, m("span", {
    className: "StoryChainBook-spine"
  }), m("span", {
    className: "StoryChainBook-face"
  }, m("span", {
    className: "StoryChainBook-kicker"
  }, t('story.chapter')), m("span", {
    className: "StoryChainBook-title"
  }, story.title), m("span", {
    className: "StoryChainBook-rule"
  }, "\u2766"), size === 'normal' && m("span", {
    className: "StoryChainBook-meta"
  }, t('story.lines', {
    count: story.lines
  }), " \xB7 ", t('story.writers', {
    count: story.contributors
  }))));
}
let ticking = 0;
let clock;

/** One shared one-second tick while any countdown is on screen (and the tab is seen). */
export function useClock() {
  if (!ticking++) clock = window.setInterval(() => !document.hidden && m.redraw(), 1000);
  return () => {
    if (! --ticking) clearInterval(clock);
  };
}
export function date(iso) {
  try {
    return new Intl.DateTimeFormat(app.translator.getLocale() || undefined, {
      month: 'long',
      day: 'numeric',
      year: 'numeric'
    }).format(new Date(iso));
  } catch {
    return new Date(iso).toLocaleDateString();
  }
}
flarum.reg.add('ernestdefoe-story-chain', 'forum/components/parts', { pushUsers: pushUsers,user: user,Person: Person,Book: Book,useClock: useClock,date: date, });